const payload = $input.first().json;
const required = ['owner_id', 'farm_id', 'production_type', 'sync_timestamp', 'data'];
const validTypes = ['cattle', 'swine', 'poultry'];

for (const field of required) {
  if (payload[field] === undefined || payload[field] === null || payload[field] === '') {
    throw new Error(`Validation failed: missing required field '${field}'`);
  }
}

if (!validTypes.includes(payload.production_type)) {
  throw new Error(`Validation failed: production_type must be one of [${validTypes.join(', ')}], received '${payload.production_type}'`);
}

if (typeof payload.data !== 'object' || Array.isArray(payload.data) || payload.data === null) {
  throw new Error("Validation failed: 'data' must be a non-null object");
}

return [{ json: { ...payload, validated_at: new Date().toISOString() } }];

const p = $input.first().json;
const d = p.data;
let normalized_data;

if (p.production_type === 'cattle') {
  normalized_data = {
    head_count: d.head_count ?? 0,
    average_weight_kg: d.average_weight_kg ?? 0,
    health_alert_count: Array.isArray(d.health_alerts) ? d.health_alerts.length : 0,
    health_alerts: d.health_alerts ?? [],
    feeding_efficiency_pct: d.feeding_efficiency_pct ?? null,
    pregnancy_count: d.pregnancy_count ?? 0
  };
} else if (p.production_type === 'swine') {
  normalized_data = {
    head_count: d.head_count ?? 0,
    average_weight_kg: d.average_weight_kg ?? 0,
    health_alert_count: Array.isArray(d.health_alerts) ? d.health_alerts.length : 0,
    health_alerts: d.health_alerts ?? [],
    gestation_count: d.gestation_count ?? 0,
    mortality_rate_pct: d.mortality_rate_pct ?? null,
    feed_conversion_ratio: d.feed_conversion_ratio ?? null
  };
} else {
  normalized_data = {
    flock_size: d.flock_size ?? 0,
    average_weight_kg: d.average_weight_kg ?? 0,
    egg_production_count: d.egg_production_count ?? 0,
    health_alert_count: Array.isArray(d.health_alerts) ? d.health_alerts.length : 0,
    health_alerts: d.health_alerts ?? [],
    feed_conversion_ratio: d.feed_conversion_ratio ?? null,
    mortality_rate_pct: d.mortality_rate_pct ?? null
  };
}

return [{
  json: {
    owner_id: p.owner_id,
    farm_id: p.farm_id,
    production_type: p.production_type,
    sync_timestamp: p.sync_timestamp,
    validated_at: p.validated_at,
    normalized_data
  }
}];

const supabaseResult = $input.first().json;
const upstream = $('Normalize Payload').first().json;

if (!Array.isArray(supabaseResult) || supabaseResult.length === 0) {
  throw new Error(`Tenant not found: farm_id=${upstream.farm_id}, owner_id=${upstream.owner_id}`);
}

const farm = supabaseResult[0];
if (!farm.is_operational) {
  throw new Error(`Farm ${upstream.farm_id} is not operational — sync rejected`);
}

return [{ json: { ...upstream, tenant_verified: true } }];
